// بازنویسی کامل «حالت‌های hover، focus و غیره» بر اساس ساختار صفحه‌ی اصلی (v4.3)
var C = window.CONTENT
var L = function () { return Array.prototype.slice.call(arguments).join('\n') }
var h2 = function (t) { return { t: 'h2', text: t } }
var h3 = function (t) { return { t: 'h3', text: t } }
var h4 = h3
var p = function (t) { return { t: 'p', text: t } }
var code = function (t, f) { return { t: 'code', text: t, file: f || 'HTML' } }
var demo = function (html, c) { return { t: 'demo', html: html, code: c } }
var note = function (t) { return { t: 'note', text: t } }
var table = function (rows, heads) { return { t: 'table', rows: rows, heads: heads } }

var person = function (name, mail, cls) {
  return '<li class="flex items-center gap-3 py-3 ' + (cls || '') + '"><div class="size-9 shrink-0 rounded-full bg-gradient-to-br from-sky-400 to-indigo-500"></div><div class="min-w-0"><p class="text-sm font-medium text-slate-900 dark:text-white">' + name + '</p><p class="truncate text-sm text-slate-500">' + mail + '</p></div></li>'
}
var row = function (n, t, e, cls) {
  return '<tr class="' + cls + '"><td class="px-3 py-2">' + n + '</td><td class="px-3 py-2">' + t + '</td><td class="px-3 py-2">' + e + '</td></tr>'
}

