var refBlocks = []
ref.forEach(function (r) {
  refBlocks.push(h3(':' + r[0].replace(/^(first|last|only|odd|even)$/, '$1').replace(/^nth.*/, r[0] + '()')))
  refBlocks.push(p(r[1] + ' با variant ‌ی `' + r[0] + '`:'))
  refBlocks.push(code(r[2]))
})

